<script setup>
import { ref, onMounted, onUnmounted, watch, nextTick, computed } from "vue";
import { useDashboardStore } from "@/stores/dashboardStore";
import * as echarts from "echarts";

const store = useDashboardStore();

const userSortBy = ref("tokens");
const userRankingsList = computed(() => {
  return userSortBy.value === "tokens"
    ? store.tokenTopUsers
    : store.callsTopUsers;
});

const filteredModelsTable = computed(() => {
  if (!store.rawModelDistribution) return [];
  const filtered =
    store.selectedProvider === "All"
      ? store.rawModelDistribution
      : store.rawModelDistribution.filter(
          (m) => (m.provider || "openai") === store.selectedProvider,
        );

  const grouped = filtered.reduce((acc, curr) => {
    const key = `${curr.provider || "openai"}/${curr.model}`;
    if (!acc[key]) {
      acc[key] = {
        model: curr.model,
        provider: curr.provider || "openai",
        callCount: 0,
        totalTokens: 0,
        promptTokens: 0,
        candidatesTokens: 0,
        cacheHitTokens: 0,
        cacheMissTokens: 0,
      };
    }
    acc[key].callCount += curr.callCount || 0;
    acc[key].totalTokens += curr.totalTokens || 0;
    acc[key].promptTokens += curr.promptTokens || 0;
    acc[key].candidatesTokens += curr.candidatesTokens || 0;
    acc[key].cacheHitTokens += curr.cacheHitTokens || 0;
    acc[key].cacheMissTokens += curr.cacheMissTokens || 0;
    return acc;
  }, {});

  return Object.values(grouped).sort((a, b) => b.totalTokens - a.totalTokens);
});

function getProviderTagType(prov) {
  const p = (prov || "").toLowerCase();
  if (p.includes("openai") || p.includes("deepseek")) return "success";
  if (p.includes("gemini") || p.includes("google")) return "warning";
  if (p.includes("anthropic") || p.includes("claude")) return "danger";
  return "info";
}

let modelsChart = null;
let themeObserver = null;

function formatTokens(t) {
  if (!t && t !== 0) return "0";
  if (t >= 1000000) return (t / 1000000).toFixed(2) + "m";
  if (t >= 1000) return (t / 1000).toFixed(1) + "k";
  return t.toString();
}

function formatNumber(num) {
  if (!num && num !== 0) return "0";
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

function getChartTheme() {
  const isDark =
    typeof document !== "undefined" &&
    (document.documentElement.getAttribute("data-theme") === "dark" ||
      document.documentElement.classList.contains("dark"));
  return {
    isDark,
    backgroundColor: "transparent",
    textStyle: {
      color: isDark ? "#94a3b8" : "#64748b",
      fontFamily: "Plus Jakarta Sans, sans-serif",
    },
    grid: {
      left: "3%",
      right: "4%",
      bottom: "3%",
      containLabel: true,
      borderColor: isDark ? "#334155" : "#f1f5f9",
    },
    tooltip: {
      backgroundColor: isDark ? "#1e293b" : "#ffffff",
      borderColor: isDark ? "#334155" : "#e2e8f0",
      borderWidth: 1,
      textStyle: {
        color: isDark ? "#f8fafc" : "#0f172a",
        fontFamily: "Plus Jakarta Sans, sans-serif",
      },
      borderRadius: 8,
      boxShadow: isDark
        ? "0 4px 12px rgba(0, 0, 0, 0.4)"
        : "0 4px 12px rgba(0, 0, 0, 0.05)",
    },
  };
}

function initChart() {
  const el = document.getElementById("provider-models-chart");
  if (el && el.clientWidth > 0 && el.clientHeight > 0) {
    if (!modelsChart || modelsChart.isDisposed()) {
      modelsChart = echarts.init(el);
    }
  }
}

function renderChart() {
  if (!store.rawModelDistribution) return;
  initChart();
  if (!modelsChart) return;

  const theme = getChartTheme();

  // Filter models
  const filtered =
    store.selectedProvider === "All"
      ? store.rawModelDistribution
      : store.rawModelDistribution.filter(
          (m) => (m.provider || "openai") === store.selectedProvider,
        );

  // Group duplicate models
  const modelMap = filtered.reduce((acc, curr) => {
    const key = curr.model || "unknown";
    acc[key] = (acc[key] || 0) + (curr.totalTokens || 0);
    return acc;
  }, {});

  const chartData = Object.entries(modelMap)
    .map(([name, value]) => ({
      name,
      value,
    }))
    .sort((a, b) => b.value - a.value);

  modelsChart.setOption(
    {
      backgroundColor: theme.backgroundColor,
      textStyle: theme.textStyle,
      tooltip: {
        ...theme.tooltip,
        trigger: "item",
        formatter: "{b}: {c} ({d}%)",
      },
      color: ["#3b82f6", "#10b981", "#6366f1", "#f59e0b", "#ec4899", "#94a3b8"],
      series: [
        {
          type: "pie",
          radius: ["45%", "70%"],
          avoidLabelOverlap: false,
          itemStyle: {
            borderRadius: 6,
            borderColor: theme.isDark ? "#1e293b" : "#ffffff",
            borderWidth: 2,
          },
          label: {
            show: true,
            color: theme.isDark ? "#cbd5e1" : "#475569",
            formatter: "{b}\n{d}%",
            fontFamily: "Plus Jakarta Sans, sans-serif",
          },
          emphasis: { label: { show: true, fontSize: 13, fontWeight: "bold" } },
          data:
            chartData.length > 0 ? chartData : [{ name: "无数据", value: 0 }],
        },
      ],
    },
    true,
  );
}

function selectProvider(name) {
  store.selectedProvider = name;
  nextTick(() => {
    initChart();
    renderChart();
  });
}

watch(
  () => store.historicalData,
  () => {
    nextTick(() => {
      initChart();
      renderChart();
    });
  },
  { deep: true },
);

watch(
  () => store.loadingOverview,
  (loading) => {
    if (!loading) {
      nextTick(() => {
        initChart();
        renderChart();
        handleResize();
      });
    }
  },
);

function handleResize() {
  const el = document.getElementById("provider-models-chart");
  if (el && el.clientWidth > 0 && el.clientHeight > 0) {
    if (!modelsChart || modelsChart.isDisposed()) {
      initChart();
      renderChart();
    } else {
      modelsChart.resize();
    }
  }
}

let resizeObserver = null;

onMounted(() => {
  nextTick(() => {
    initChart();
    renderChart();
    if (typeof window !== "undefined") {
      window.addEventListener("resize", handleResize);
    }

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(() => {
        handleResize();
      });
      const el = document.getElementById("provider-models-chart");
      if (el) resizeObserver.observe(el);
    }

    if (typeof document !== "undefined") {
      themeObserver = new MutationObserver(() => {
        renderChart();
      });
      themeObserver.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["data-theme", "class"],
      });
    }
  });
});

onUnmounted(() => {
  if (typeof window !== "undefined") {
    window.removeEventListener("resize", handleResize);
  }
  resizeObserver?.disconnect();
  themeObserver?.disconnect();
  modelsChart?.dispose();
  modelsChart = null;
});
</script>

